/* @autogenerated */
package net.civeira.phylax.feature.oauth.consent.infrastructure.driven;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.oauth.consent.domain.TermsOfUseAcceptance;
import net.civeira.phylax.testing.sql.OidcRepositories;

/** The acceptance of the terms of use of a tenant stored with the repositories on h2. */
class TermsOfUseConsentAdapterUnitTest {
  private static final List<String> AUDIENCES = List.of("web");

  private OidcRepositories store;
  private TermsOfUseConsentAdapter terms;
  private String alice;
  private String current;
  private String previous;
  private String foreign;

  @BeforeEach
  void setUp() {
    store = new OidcRepositories();
    String tenant = store.tenant("acme");
    String other = store.tenant("globex");
    alice = store.user(tenant, "alice", "alice@acme.test");
    current = terms(tenant, "Current", true, "-1");
    previous = terms(tenant, "Previous", true, "-2");
    terms(tenant, "Disabled", false, "-3");
    terms(tenant, "Draft", true, null);
    terms(tenant, "Future", true, "2");
    foreign = terms(other, "Foreign", true, "-1");
    terms = new TermsOfUseConsentAdapter(store.tenants(), store.users(), store.termsOfUse(),
        store.acceptedTerms(), store.acceptedTermsWriter());
  }

  /** Terms active since (or from) the given days from now, null without activation. */
  private String terms(String tenant, String text, boolean enabled, String days) {
    String uid = OidcRepositories.uid();
    String activation = days == null ? "NULL" : "DATEADD('DAY', " + days + ", CURRENT_TIMESTAMP)";
    store.db()
        .execute("INSERT INTO identity_tenant_terms_of_use (uid, version, activation_date,"
            + " enabled, text, tenant) VALUES ('" + uid + "', 1, " + activation + ", " + enabled
            + ", '" + text + "', '" + tenant + "')");
    return uid;
  }

  private List<TermsOfUseAcceptance> pending() {
    return terms.getPendingConsent("acme", "alice", AUDIENCES);
  }

  private void accept(String tenant, String user, String uid) {
    terms.storeAcceptedConsent(tenant, user, AUDIENCES, new TermsOfUseAcceptance(uid, "text"));
  }

  @Test
  @DisplayName("Only the enabled and active terms are pending, the oldest first")
  void pending_terms() {
    Assertions.assertEquals(List.of(new TermsOfUseAcceptance(previous, "Previous"),
        new TermsOfUseAcceptance(current, "Current")), pending());
  }

  @Test
  @DisplayName("Accepted terms are stored once with their date and not asked again")
  void accept_terms() {
    accept("acme", "alice", previous);

    Assertions.assertEquals(List.of(new TermsOfUseAcceptance(current, "Current")), pending());
    Assertions.assertEquals(previous,
        store.value("SELECT terms_of_use FROM identity_user_accepted_terms_of_use WHERE `user` = '"
            + alice + "'"));
    Assertions
        .assertNotNull(store.value("SELECT accept_date FROM identity_user_accepted_terms_of_use"));

    accept("acme", "alice", previous);
    Assertions.assertEquals(1, store.db().count("identity_user_accepted_terms_of_use", null),
        "Accepting again does not duplicate the acceptance");
  }

  @Test
  @DisplayName("Unknown terms, those of other tenants and unknown users store nothing")
  void unknown() {
    accept("acme", "alice", "missing");
    accept("acme", "alice", foreign);
    accept("acme", "bob", current);
    accept("initech", "alice", current);

    Assertions.assertEquals(0, store.db().count("identity_user_accepted_terms_of_use", null));
    Assertions.assertEquals(List.of(), terms.getPendingConsent("acme", "bob", AUDIENCES));
    Assertions.assertEquals(2, pending().size());
  }
}
